{
  "name": "Luminos精密电动定位台",
  "name_en": "Luminos Precision Motorized Positioning Stage",
  "manufacturer": "Zaber Technologies",
  "description": "Luminos 精密电动定位台是一类用于实验室精密定位与光学对准的电动平台，可配置线性轴和旋转轴，用于调整样品、探针、光纤或光学元件的位置与姿态。设备支持回零、相对/绝对移动，以及速度、加速度和微步等运动参数设置，也可在计算机控制与手动旋钮操作之间切换。",
  "description_en": "The Luminos precision motorized positioning stage is a laboratory motion platform for precise positioning and optical alignment. It can include linear and rotary axes for adjusting the position and orientation of samples, probes, fibers, or optical components. The device supports homing, relative and absolute moves, and motion settings such as speed, acceleration, and microstep resolution, with both computer-controlled and manual knob operation.",
  "tag_hints": [
    "motorized positioning stage",
    "optical alignment",
    "precision motion control",
    "linear and rotary axes",
    "microstepping",
    "sample positioning",
    "fiber alignment"
  ],
  "actions": [
    {
      "action_name": "auto-set_default_settings",
      "description": "恢复默认设置",
      "description_en": "restore default settings"
    },
    {
      "action_name": "auto-set_manual_mode",
      "description": "切换到手动模式",
      "description_en": "switch to manual mode"
    },
    {
      "action_name": "auto-set_computer_mode",
      "description": "切换到计算机控制模式",
      "description_en": "switch to computer control mode"
    },
    {
      "action_name": "auto-home",
      "description": "执行回零",
      "description_en": "home the stage"
    },
    {
      "action_name": "auto-flash_leds",
      "description": "闪烁指示灯",
      "description_en": "flash the LEDs"
    },
    {
      "action_name": "auto-move_rel",
      "description": "相对移动位移台",
      "description_en": "move the stage by a relative amount"
    },
    {
      "action_name": "auto-move_abs",
      "description": "移动位移台到绝对位置",
      "description_en": "move the stage to an absolute position"
    },
    {
      "action_name": "auto-get_device_mode_bit_status",
      "description": "获取设备模式位状态",
      "description_en": "get device mode bit status"
    },
    {
      "action_name": "auto-turn_leds_off",
      "description": "关闭指示灯",
      "description_en": "turn off the LEDs"
    },
    {
      "action_name": "auto-turn_leds_on",
      "description": "打开指示灯",
      "description_en": "turn on the LEDs"
    },
    {
      "action_name": "auto-enable_motor_knob",
      "description": "启用电机旋钮手动控制",
      "description_en": "enable the motor knob"
    },
    {
      "action_name": "auto-disable_motor_knob",
      "description": "禁用电机旋钮手动控制",
      "description_en": "disable the motor knob"
    },
    {
      "action_name": "auto-enable_manual_move_reply",
      "description": "启用手动移动回报",
      "description_en": "enable manual move reply"
    },
    {
      "action_name": "auto-disable_manual_move_reply",
      "description": "禁用手动移动回报",
      "description_en": "disable manual move reply"
    },
    {
      "action_name": "auto-enable_circular_phase_microstepping",
      "description": "启用圆相位微步",
      "description_en": "enable circular phase microstepping"
    },
    {
      "action_name": "auto-disable_circular_phase_microstepping",
      "description": "禁用圆相位微步",
      "description_en": "disable circular phase microstepping"
    },
    {
      "action_name": "auto-enable_anti_backlash_routine",
      "description": "启用消隙程序",
      "description_en": "enable anti-backlash routine"
    },
    {
      "action_name": "auto-disable_anti_backlash_routine",
      "description": "禁用消隙程序",
      "description_en": "disable anti-backlash routine"
    },
    {
      "action_name": "auto-enable_anti_sticktion_routine",
      "description": "启用抗静摩擦程序",
      "description_en": "enable anti-stiction routine"
    },
    {
      "action_name": "auto-disable_anti_sticktion_routine",
      "description": "禁用抗静摩擦程序",
      "description_en": "disable anti-stiction routine"
    },
    {
      "action_name": "auto-enable_move_tracking",
      "description": "启用运动跟踪",
      "description_en": "enable move tracking"
    },
    {
      "action_name": "auto-disable_move_tracking",
      "description": "禁用运动跟踪",
      "description_en": "disable move tracking"
    },
    {
      "action_name": "auto-get_speed",
      "description": "获取速度",
      "description_en": "get speed"
    },
    {
      "action_name": "auto-set_speed",
      "description": "设置速度",
      "description_en": "set speed"
    },
    {
      "action_name": "auto-get_acceleration",
      "description": "获取加速度",
      "description_en": "get acceleration"
    },
    {
      "action_name": "auto-set_acceleration",
      "description": "设置加速度",
      "description_en": "set acceleration"
    },
    {
      "action_name": "auto-get_microstep_resolution",
      "description": "获取微步分辨率",
      "description_en": "get microstep resolution"
    },
    {
      "action_name": "auto-set_microstep_resolution",
      "description": "设置微步分辨率",
      "description_en": "set microstep resolution"
    },
    {
      "action_name": "auto-nm_per_step",
      "description": "获取每步对应的纳米位移",
      "description_en": "get nanometers per step"
    },
    {
      "action_name": "auto-arc_second_per_step",
      "description": "获取每步对应的角秒位移",
      "description_en": "get arcseconds per step"
    }
  ]
}

